shellCommands.command:
(nohup npx vite preview --port 4173 --strictPort > /tmp/e2e/preview.log 2>&1 &) ; sleep 4; cat /tmp/e2e/preview.log; cat > /tmp/e2e/check.mjs <<'EOF'
import { chromium } from 'playwright';

const URL = 'http://localhost:4173/';
const browser = await chromium.launch();
const page = await browser.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

const bodyTheme = () => page.evaluate(() => [...document.body.classList].filter((c) => c.includes('theme')).join(' '));
const checked = () => page.evaluate(() => {
  const el = document.querySelector('input[name="theme"]:checked');
  return el ? el.value : null;
});
const stored = () => page.evaluate(() => localStorage.getItem('theme'));
const results = [];
const check = (name, cond, extra = '') => results.push(`${cond ? 'PASS' : 'FAIL'} ${name} ${extra}`);

await page.goto(URL);
await page.waitForSelector('input[name="theme"]', { state: 'attached' });
check('initial: default light body class', (await bodyTheme()).includes('root_theme_light'), `[${await bodyTheme()}]`);
check('initial: light option checked', (await checked()) === 'light', `[${await checked()}]`);
check('initial: nothing stored yet', (await stored()) === null);

await page.locator('label', { hasText: 'Тёмная' }).click();
await page.waitForTimeout(200);
check('click dark: body class dark', (await bodyTheme()).includes('root_theme_dark'), `[${await bodyTheme()}]`);
check('click dark: stored', (await stored()) === 'dark', `[${await stored()}]`);
const bgDark = await page.evaluate(() => getComputedStyle(document.body).backgroundColor);
check('click dark: body background changed', bgDark !== 'rgb(255, 255, 255)', bgDark);

await page.reload();
await page.waitForSelector('input[name="theme"]', { state: 'attached' });
check('reload: dark restored on body', (await bodyTheme()).includes('root_theme_dark'), `[${await bodyTheme()}]`);
check('reload: dark option checked', (await checked()) === 'dark', `[${await checked()}]`);

await page.locator('label', { hasText: 'Системная' }).click();
await page.waitForTimeout(200);
check('click system: stored', (await stored()) === 'system');
await page.reload();
await page.waitForSelector('input[name="theme"]', { state: 'attached' });
check('reload: system restored', (await checked()) === 'system', `[${await checked()}]`);

await page.evaluate(() => localStorage.setItem('theme', 'purple'));
await page.reload();
await page.waitForSelector('input[name="theme"]', { state: 'attached' });
check('invalid stored value: falls back to light', (await checked()) === 'light' && (await bodyTheme()).includes('root_theme_light'), `[${await checked()}]`);

check('no page/console errors', errors.length === 0, errors.join(' | '));

console.log(results.join('\n'));
await browser.close();
EOF
cd /tmp/e2e && node check.mjs

pkill -f "vite preview" 2>/dev/null; cat > /tmp/e2e/storage-check.mjs <<'EOF'
const mem = new Map();
globalThis.localStorage = {
  getItem: (k) => (mem.has(k) ? mem.get(k) : null),
  setItem: (k, v) => mem.set(k, String(v)),
};
const { loadThemeChoice, saveThemeChoice, THEME_STORAGE_KEY } = await import('/home/sandbox/workspace/src/theme.ts');
const out = [];
const eq = (name, a, b) => out.push(`${a === b ? 'PASS' : 'FAIL'} ${name}: got ${JSON.stringify(a)}`);
eq('empty storage -> light', loadThemeChoice(), 'light');
saveThemeChoice('dark');
eq('stored dark is persisted under key', mem.get(THEME_STORAGE_KEY), 'dark');
eq('load after save -> dark', loadThemeChoice(), 'dark');
saveThemeChoice('system');
eq('load after save -> system', loadThemeChoice(), 'system');
mem.set(THEME_STORAGE_KEY, 'purple');
eq('invalid value -> light', loadThemeChoice(), 'light');
globalThis.localStorage = { getItem() { throw new Error('denied'); }, setItem() { throw new Error('denied'); } };
eq('storage throws on read -> light', loadThemeChoice(), 'light');
let threw = false; try { saveThemeChoice('dark'); } catch { threw = true; }
eq('storage throws on write -> no exception', threw, false);
console.log(out.join('\n'));
EOF
cd /tmp/e2e && node --experimental-strip-types storage-check.mjs 2>&1 | grep -v ExperimentalWarning
